import{_ as t,o as a,c as s,aa as i}from"./chunks/framework.oWfRcsIL.js";const g=JSON.parse('{"title":"Data residency and data handling","description":"Which data reaches AI models, how the data residency setting limits model choice, and how project data is deleted.","frontmatter":{"title":"Data residency and data handling","description":"Which data reaches AI models, how the data residency setting limits model choice, and how project data is deleted."},"headers":[],"relativePath":"legal/data-handling.md","filePath":"legal/data-handling.md"}'),n={name:"legal/data-handling.md"};function o(d,e,r,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="data-residency-and-data-handling" tabindex="-1">Data residency and data handling <a class="header-anchor" href="#data-residency-and-data-handling" aria-label="Permalink to &quot;Data residency and data handling&quot;">​</a></h1><h2 id="which-data-reaches-the-ai-models" tabindex="-1">Which data reaches the AI models <a class="header-anchor" href="#which-data-reaches-the-ai-models" aria-label="Permalink to &quot;Which data reaches the AI models&quot;">​</a></h2><p>The agents use AI models (LLMs). Everything an agent works with is sent to the model that runs it. That includes:</p><ul><li>responses from the target system, including any personal or confidential data the application returns;</li><li>the test account credentials and account manager credentials you provide;</li><li>uploaded source code, mobile apps and reference documents;</li><li>the project&#39;s notes, scope and findings.</li></ul><p>Test against <a href="/getting-started/test-accounts">staging systems with test data</a> wherever possible, so that no real personal data reaches a model in the first place.</p><h2 id="data-residency" tabindex="-1">Data residency <a class="header-anchor" href="#data-residency" aria-label="Permalink to &quot;Data residency&quot;">​</a></h2><p>syslifters.ai itself is hosted within the EU. The project, its evidence and the agents&#39; working data stay on that infrastructure.</p><p>Every project has a <strong>Data residency</strong> setting. It limits which models the project may use, based on where each model processes data.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Models the project may use</th></tr></thead><tbody><tr><td><strong>Local only</strong></td><td>Only models that run on infrastructure operated by Syslifters.</td></tr><tr><td><strong>EU only</strong></td><td>Local models, plus models that process data within the EU.</td></tr><tr><td><strong>Unrestricted</strong></td><td>Any model, including providers that process data outside the EU.</td></tr></tbody></table><p>With <strong>EU only</strong>, syslifters.ai and every model the project uses both process data inside the EU, so all project data stays within the EU.</p><p>Choose the setting according to your agreement with the system owner and the kind of data the target holds. The setting is enforced strictly:</p><ul><li>The model picker greys out every model the setting does not allow.</li><li>Before every agent starts, the model is checked against the setting. If the model is not allowed (or its data location is unknown), the agent does not start and the workspace shows an error. A run never falls back to a model outside your setting.</li></ul><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><p>Agents&#39; traffic to the target is recorded as evidence: requests and responses, screenshots and the agents&#39; notes. The evidence is kept with the project so you can review and reproduce findings, and it is used for the report.</p><h2 id="deleting-a-project" tabindex="-1">Deleting a project <a class="header-anchor" href="#deleting-a-project" aria-label="Permalink to &quot;Deleting a project&quot;">​</a></h2><p><strong>Delete</strong> in the project workspace removes the project and all of its data: the knowledge, findings, approvals, evidence, recorded traffic, uploaded files and the agents&#39; working data. Deletion cannot be undone.</p><ul><li>Pause a running project before deleting it.</li><li>To confirm, you type the project&#39;s name.</li><li>A linked <strong>SysReptor report is not deleted</strong>. It lives on the reporting platform; delete it there if needed.</li></ul><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> I chose the data residency setting according to my agreement with the system owner.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> I know that syslifters.ai is hosted in the EU, and that <strong>EU only</strong> keeps all project data within the EU — on syslifters.ai and on the models.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> I know that target responses, credentials and uploaded files are processed by the selected model.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> I prefer staging systems with test data so no real personal data is processed.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> I know that deleting the project does not delete the SysReptor report.</li></ul>',19)])])}const m=t(n,[["render",o]]);export{g as __pageData,m as default};
